previewCss:
.darma-loader-darma-b11-jellyfish { --accent: var(--loader-color, #a855f7); --accent-2: var(--loader-secondary-color, #ec4899); width: var(--loader-size, 88px); height: var(--loader-size, 88px); position: relative; display: grid; place-items: center; }
.darma-loader-darma-b11-jellyfish .darma-loader-darma-b11-jellyfish__bell { position: relative; width: 46%; height: 34%; background: radial-gradient(circle at 45% 32%, color-mix(in srgb, #fff 45%, var(--accent)), var(--accent) 68%, var(--accent-2)); border-radius: 50% 50% 32% 32%; box-shadow: 0 0 calc(var(--loader-size, 88px) * .16) color-mix(in srgb, var(--accent) 45%, transparent); animation: darma-loader-darma-b11-jellyfish-jelly-pulse calc(var(--loader-speed, 1s) * 1.8) ease-in-out infinite; }
.darma-loader-darma-b11-jellyfish .darma-loader-darma-b11-jellyfish__bell::after { content: ''; position: absolute; top: 88%; left: 6%; width: 88%; height: 130%; background: repeating-linear-gradient(90deg, var(--accent) 0 9%, transparent 9% 20%); -webkit-mask: linear-gradient(#000, transparent 88%); mask: linear-gradient(#000, transparent 88%); border-radius: 0 0 40% 40%; transform-origin: 50% 0; animation: darma-loader-darma-b11-jellyfish-jelly-sway calc(var(--loader-speed, 1s) * 1.8) ease-in-out infinite; }
@keyframes darma-loader-darma-b11-jellyfish-jelly-pulse { 0%, 100% { transform: scale(1, 1); } 50% { transform: scale(1.08, .82); } }
@keyframes darma-loader-darma-b11-jellyfish-jelly-sway { 0%, 100% { transform: skewX(7deg); } 50% { transform: skewX(-7deg); } }

